class MachineOp(HWOp):
    """``fsm.machine @Name(%in: i1) -> (i1) { fsm.state ... }``.

    The body is a graph region of :class:`StateOp` operations.  ``fsm.machine``
    is listed in the parser's ``PORT_LIST_OPS``, so a parsed machine carries the
    same ``sym_name`` / ``function_type`` / ``port_names`` / ``port_directions``
    attributes as ``hw.module`` and exposes them through :attr:`ports`.

    The machine is also an interpreter: :attr:`current_state` starts at
    :attr:`initial_state`, :meth:`step` advances it by one transition and
    :meth:`run` replays a list of per-cycle environments.
    """

    OPERATION_NAME = "fsm.machine"
    TRAITS = (Trait.SYMBOL, Trait.ISOLATED_FROM_ABOVE, Trait.GRAPH_REGION)

    #: Class-level defaults so attribute access never raises on an operation
    #: created by ``build_parsed``, which bypasses ``__init__``.
    encoding: StateEncoding = StateEncoding.BINARY
    _current_state: Optional[str] = None

    def __init__(
        self,
        name: Optional[str] = None,
        initial_state: Optional[str] = None,
        encoding: Union[str, StateEncoding] = StateEncoding.BINARY,
        states: Optional[Sequence[StateOp]] = None,
        ports: Optional[Sequence[Port]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        port_list = list(ports or ())
        attrs: Dict[str, Attribute] = dict(attributes or {})
        if name:
            attrs.setdefault("sym_name", StringAttr(name))
        if initial_state:
            attrs.setdefault("initialState", StringAttr(initial_state))
        resolved = StateEncoding.parse(encoding)
        attrs.setdefault("stateEncoding", StringAttr(resolved.value))
        if port_list:
            attrs.setdefault(
                "port_names", ArrayAttr([StringAttr(p.name) for p in port_list])
            )
            attrs.setdefault(
                "port_directions",
                ArrayAttr([StringAttr(p.direction.value) for p in port_list]),
            )
            attrs.setdefault(
                "function_type",
                TypeAttr(
                    FunctionType(
                        [p.port_type for p in port_list if not p.is_output and p.port_type],
                        [p.port_type for p in port_list if p.is_output and p.port_type],
                    )
                ),
            )
        super().__init__(attributes=attrs, location=location)
        self.encoding = resolved
        self._current_state = None

        block = self.add_region(Region()).add_block(Block())
        for port in port_list:
            if not port.is_output:
                block.add_argument(port.port_type or IntType(1), port.name)
        for state in states or ():
            block.append(state)

    @classmethod
    def default_num_results(cls) -> int:
        return 0

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        declared = _string_attr(op, "stateEncoding", "encoding")
        try:
            op.encoding = StateEncoding.parse(declared) if declared else StateEncoding.BINARY
        except ValueError:
            op.encoding = StateEncoding.BINARY
        op._current_state = None
        return op

    # -- structure --------------------------------------------------------
    @property
    def machine_name(self) -> Optional[str]:
        attr = self.attributes.get("sym_name")
        return attr.value if attr is not None else None

    #: ``Operation.name`` is the mnemonic, so the symbol is also spelled out
    #: under the MLIR-standard ``sym_name`` name.
    @property
    def sym_name(self) -> Optional[str]:
        return self.machine_name

    @property
    def block(self) -> Optional[Block]:
        if not self.regions or not self.regions[0].blocks:
            return None
        return self.regions[0].blocks[0]

    @property
    def body(self) -> List[Operation]:
        """The operations in the machine body, in textual order."""
        return [op for region in self.regions for op in region.operations]

    @property
    def ports(self) -> List[Port]:
        """The machine's ports, when it was built from a port list.

        Decoding ``port_names`` / ``port_directions`` / ``function_type`` is
        identical to ``hw.module``, so reuse that accessor instead of repeating
        the input/output index bookkeeping.
        """
        return HWModuleOp.ports.fget(self)  # type: ignore[attr-defined]

    @property
    def input_ports(self) -> List[Port]:
        return [p for p in self.ports if not p.is_output]

    @property
    def output_ports(self) -> List[Port]:
        return [p for p in self.ports if p.is_output]

    # -- states -----------------------------------------------------------
    @property
    def states(self) -> List[StateOp]:
        return [
            op
            for op in self.body
            if isinstance(op, StateOp) or op.name == StateOp.OPERATION_NAME
        ]

